-- Expenses, July to 4 October 2026, from the property's "Expenses_2026" sheet.
--
-- July: 80 lines; 1,720,910.48 counted, 3 held for checking (37,705.00).
-- August: 135 lines; 528,786.38 counted, 20 held for checking (50,451.00).
-- September: 141 lines; 782,849.35 counted, 7 held for checking (78,959.00).
-- October: 12 lines; 50,098.00 counted, 0 held for checking (0.00).
-- In all 3,082,644.21 counted and 167,115.00 held.
--
-- Held (exp_review_note set, see 072_expense_review.sql): the 23 lines the
-- sheet itself marks "possible duplicate" and leaves out of its totals, and 6
-- hand-written lines that are a bill-sheet line with its cents rounded off,
-- and July#46 (Accommodation Payment), whose 30,000 may be 13,000.
-- They stay out of every total until someone with the bills counts or deletes
-- them on the Accounting page, so the counted figures are the sheet's own
-- totals less those 7 lines. A line whose amount matches an expense already
-- typed into the system (same day, or for an undated line the same month and
-- category) is held
-- as well, so nothing is counted twice.
--
-- Hand-written lines with no date are put on the last day of their month
-- ("date not on sheet" in the description). "Petty cash" is cash, "Cheque" is
-- a cheque; otherwise how it was paid is not on the sheet and is left blank.
-- The categories are a best reading of each description; any can be changed
-- on the Accounting page. Runs once: nothing is added if the sheet's lines are
-- already there.
INSERT INTO "EXPENSE_CATEGORY" (b_id, name, department)
SELECT b."B_id", v.name, v.department
FROM "Branch" b
CROSS JOIN (VALUES
  ('Fuel & Transport', 'shared'),
  ('Kitchen Gas', 'restaurant'),
  ('Laundry', 'hotel'),
  ('Office & Housekeeping', 'shared'),
  ('Furniture & Equipment', 'shared'),
  ('Staff Welfare', 'shared'),
  ('Accommodation', 'hotel'),
  ('Fees, Insurance & Taxes', 'shared')
) AS v (name, department)
WHERE b."B_name" ILIKE 'Regent Heights%'
ON CONFLICT (b_id, lower(name)) DO NOTHING;

INSERT INTO "EXPENSE" (b_id, exp_category, exp_amount, exp_description, exp_date, exp_method, exp_review_note, exp_source)
SELECT b."B_id",
       COALESCE((SELECT c.name FROM "EXPENSE_CATEGORY" c WHERE c.b_id = b."B_id" AND lower(c.name) = lower(v.cat)), v.cat),
       v.amount, v.descr, v.day, v.method,
       COALESCE(v.note, (
         SELECT 'Possibly already entered in the system: ' || e.exp_category || ' ' || e.exp_amount || ' on ' || to_char(e.exp_date, 'DD/MM')
                || COALESCE(' (' || e.exp_description || ')', '')
           FROM "EXPENSE" e
          WHERE e.b_id = b."B_id" AND e.exp_source IS NULL
            AND abs(e.exp_amount - v.amount) <= 1
            AND (e.exp_date = v.day OR (v.undated AND date_trunc('month', e.exp_date) = date_trunc('month', v.day) AND lower(e.exp_category) = lower(v.cat)))
          ORDER BY e.exp_id LIMIT 1)),
       'expenses-sheet-2026:' || v.line
FROM "Branch" b
